import java.util.BitSet;
import java.util.concurrent.locks.ReadWriteLock;
import java.util.concurrent.locks.ReentrantReadWriteLock;

public class ThreadSafeBloomFilter {
    private final BitSet bitSet;
    private final int size;
    private final int numHashFunctions;
    private final ReadWriteLock lock = new ReentrantReadWriteLock();

    public ThreadSafeBloomFilter(int sizeInBits, int numHashFunctions) {
        this.size = sizeInBits;
        this.numHashFunctions = numHashFunctions;
        this.bitSet = new BitSet(sizeInBits);
    }

    public void add(String item) {
        lock.writeLock().lock();
        try {
            int[] hashValues = computeHashes(item);
            for (int hash : hashValues) {
                bitSet.set(Math.abs(hash % size));
            }
        } finally {
            lock.writeLock().unlock();
        }
    }

    public boolean mightContain(String item) {
        lock.readLock().lock();
        try {
            int[] hashValues = computeHashes(item);
            for (int hash : hashValues) {
                if (!bitSet.get(Math.abs(hash % size))) {
                    return false;
                }
            }
            return true;
        } finally {
            lock.readLock().unlock();
        }
    }

    private int[] computeHashes(String item) {
        int[] result = new int[numHashFunctions];
        int h1 = item.hashCode();
        int h2 = h1ี่ >>> 16;
        for (int i = 0; i < numHashFunctions; i++) {
            result[i] = h1 + (i * h2);
        }
        return result;
    }
}
